function gm(k) {
    var v = metadata["ss_" + k];
    if (v === undefined || v === null) { v = metadata[k]; }
    return v;
}
// ===== Ventana temporal de consulta (cursor por fecha) =====
// El campo mrid llega siempre a 0 en las respuestas reales, asi que el cursor
// es la ultima fecha ingerida. La escritura de series temporales en ThingsBoard
// es idempotente por (entidad, clave, ts), de modo que el solape no duplica nada.
var SOLAPE_MS = 1800000;                       // 30 min de solape de seguridad
var ahora = Date.now();
var ultima = gm("az_ultima_fecha") ? parseInt(gm("az_ultima_fecha")) : 0;
var diasBackfill = gm("az_dias_backfill") ? parseFloat(gm("az_dias_backfill")) : 0.5;
var ventanaMax = (gm("az_ventana_max_dias") ? parseFloat(gm("az_ventana_max_dias")) : 0.5) * 86400000;

var ini = (ultima > 0) ? (ultima - SOLAPE_MS) : (ahora - diasBackfill * 86400000);
var fin = ini + ventanaMax;
if (fin > ahora) { fin = ahora; }
if (fin <= ini) { fin = ahora; }

function fmt(t) {
    var d = new Date(t);
    function p(n) { return ("0" + n).slice(-2); }
    return "" + d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate()) +
           p(d.getUTCHours()) + p(d.getUTCMinutes()) + p(d.getUTCSeconds());
}

// Ojo al orden de la URL de ag-zoom: /date/<FECHA_FIN>/<FECHA_INICIO>
metadata.az_fecha_ini = fmt(ini);
metadata.az_fecha_fin = fmt(fin);
metadata.az_ventana_h = "" + Math.round((fin - ini) / 3600000);
return { msg: msg, metadata: metadata, msgType: msgType };

