// ===== ag-zoom -> telemetria ThingsBoard (v2, ajustado a la respuesta real) =====
// Entrada: respuesta de /api/getsensordata/<id>/date/<fin>/<inicio>
// Metadata: az_mapa (JSON), az_ultima_fecha (epoch ms), tb_device
//
// Diferencias respecto al manual del fabricante, verificadas sobre datos reales:
//   - "device" es un OBJETO, no un array
//   - los sensores NO traen "depth": la clave de mapeo es <puerto>|<idVariable>
//   - "mrid" llega siempre a 0 -> el cursor es por fecha, no por mrid
//   - "date" es ISO-8601 en UTC (2026-05-28T23:45:06Z)

// Helper: atributos del lisímetro llegan con prefijo ss_ en esta instancia
function gm(k) {
    var v = metadata["ss_" + k];
    if (v === undefined || v === null) { v = metadata[k]; }
    return v;
}
var MAX_PUNTOS = 5000;   // corta payloads desmesurados en un backfill

function parseFechaUtc(s) {
    if (!s) { return null; }
    var t = "" + s;
    var y, mo, d, h, mi, se;
    if (t.indexOf("-") > 0) {
        y = parseInt(t.substr(0, 4)); mo = parseInt(t.substr(5, 2)); d = parseInt(t.substr(8, 2));
        h = parseInt(t.substr(11, 2) || "0"); mi = parseInt(t.substr(14, 2) || "0"); se = parseInt(t.substr(17, 2) || "0");
    } else {
        y = parseInt(t.substr(0, 4)); mo = parseInt(t.substr(4, 2)); d = parseInt(t.substr(6, 2));
        h = parseInt(t.substr(8, 2) || "0"); mi = parseInt(t.substr(10, 2) || "0"); se = parseInt(t.substr(12, 2) || "0");
    }
    if (isNaN(y) || isNaN(mo) || isNaN(d)) { return null; }
    return Date.UTC(y, mo - 1, d, h || 0, mi || 0, se || 0);
}

var resp = msg;
if (resp.status !== undefined && ("" + resp.status) !== "0") {
    throw new Error("API ag-zoom status=" + resp.status +
                    " error=" + (resp.errorMsg || resp.error || "?"));
}

var mapa = {};
var _mapaRaw = gm("az_mapa");
    if (_mapaRaw) {
    try { mapa = JSON.parse(_mapaRaw); } catch (e) { mapa = {}; }
}

// "device" puede venir como objeto (real) o como array (manual)
var devs = resp.device;
if (!devs) { devs = []; }
if (!Array.isArray(devs)) { devs = [devs]; }

var porTs = {};
var nOk = 0, nFuera = 0, nIgnoradas = 0;
var sinMapear = {};
var fueraRango = {};
var _uf = gm("az_ultima_fecha");
    var ultimaFecha = _uf ? parseInt(_uf) : 0;
var maxTs = ultimaFecha;

for (var i = 0; i < devs.length; i++) {
    var sensores = devs[i].sensors || [];
    for (var j = 0; j < sensores.length; j++) {
        var s = sensores[j];
        var puerto = (s.port !== undefined && s.port !== null) ? s.port : "x";
        var vars = s.variables || [];
        for (var k = 0; k < vars.length; k++) {
            var v = vars[k];
            var idx = puerto + "|" + v.id;
            var cfg = mapa[idx];

            if (cfg === false || (cfg && cfg.ignorar === true)) { nIgnoradas++; continue; }

            var clave, factor = 1, vmin = null, vmax = null, guardarRaw = false;
            if (typeof cfg === "string") {
                clave = cfg;
            } else if (cfg && cfg.k) {
                clave = cfg.k;
                if (cfg.f !== undefined) { factor = parseFloat(cfg.f); }
                if (cfg.min !== undefined) { vmin = parseFloat(cfg.min); }
                if (cfg.max !== undefined) { vmax = parseFloat(cfg.max); }
                guardarRaw = (cfg.raw === true);
            } else {
                clave = "p" + puerto + "_v" + v.id;      // fallback: nada se pierde
                sinMapear[idx] = clave + " (" + (v.type || "?") + ")";
            }

            var bruto = parseFloat(v.data);
            if (isNaN(bruto)) { continue; }
            // Centinela de "sin dato" de los dataloggers ag-zoom
            if (bruto <= -9990) { continue; }
            var valor = bruto * factor;

            var ts = parseFechaUtc(v.date);
            if (ts === null) { continue; }
            if (!porTs[ts]) { porTs[ts] = {}; }

            var valido = true;
            if (vmin !== null && valor < vmin) { valido = false; }
            if (vmax !== null && valor > vmax) { valido = false; }

            if (valido) {
                porTs[ts][clave] = valor;
                nOk++;
            } else {
                // fuera de rango fisico: no ensucia la clave limpia, pero queda trazado
                porTs[ts][clave + "_raw"] = valor;
                fueraRango[clave] = valor;
                nFuera++;
            }
            if (guardarRaw && valido) { porTs[ts][clave + "_raw"] = bruto; }

            if (ts > maxTs) { maxTs = ts; }
        }
    }
}

var tss = [];
for (var t in porTs) { if (porTs.hasOwnProperty(t)) { tss.push(parseInt(t)); } }
tss.sort(function (a, b) { return a - b; });
if (tss.length > MAX_PUNTOS) { tss = tss.slice(tss.length - MAX_PUNTOS); }

var salida = [];

if (tss.length > 0) {
    var puntos = [];
    for (var p = 0; p < tss.length; p++) {
        puntos.push({ ts: tss[p], values: porTs[tss[p]] });
    }
    var metaTel = {};
    for (var mk in metadata) { if (metadata.hasOwnProperty(mk)) { metaTel[mk] = metadata[mk]; } }
    salida.push({ msg: puntos, metadata: metaTel, msgType: "POST_TELEMETRY_REQUEST" });
}

// Cursor por fecha (el mrid llega a 0 y no sirve como cursor)
var attrs = {
    az_ultima_fecha: maxTs,
    az_ultima_sincro: Date.now(),
    az_puntos_ultima_sincro: tss.length,
    az_valores_ok: nOk,
    az_valores_fuera_rango: nFuera
};
var pend = [];
for (var sm in sinMapear) { if (sinMapear.hasOwnProperty(sm)) { pend.push(sm + " -> " + sinMapear[sm]); } }
attrs.az_sin_mapear = pend.length ? pend.join(" | ") : "";
salida.push({ msg: attrs, metadata: metadata, msgType: "POST_ATTRIBUTES_REQUEST" });

// Aviso de sensor fuera de rango (dispara alarma aguas abajo)
if (nFuera > 0) {
    var det = [];
    for (var fr in fueraRango) { if (fueraRango.hasOwnProperty(fr)) { det.push(fr + "=" + fueraRango[fr]); } }
    var metaAl = {};
    for (var mk2 in metadata) { if (metadata.hasOwnProperty(mk2)) { metaAl[mk2] = metadata[mk2]; } }
    metaAl.sensores_ko = det.join(", ");
    metaAl.n_fuera_rango = "" + nFuera;
    salida.push({ msg: { lisimetro: metadata.tb_device || "", sensores: det.join(", "), muestras: nFuera },
                  metadata: metaAl, msgType: "AGZOOM_SENSOR_KO" });
}

return salida;

