// ===== Autodescubrimiento de lisímetros desde /api/userdevices =====
// Recorre costumers -> fincas -> devices y emite un mensaje por dispositivo.
// Filtro opcional por prefijo de nombre (atributo az_prefijo, p.ej. "AGD").
if (msg.status !== undefined && ("" + msg.status) !== "0") {
    throw new Error("userdevices status=" + msg.status + " error=" + (msg.errorMsg || msg.error || "?"));
}
var prefijo = metadata.az_prefijo || "";
var salida = [];
var vistos = {};
var costumers = msg.costumers || [];
for (var c = 0; c < costumers.length; c++) {
    var fincas = costumers[c].fincas || [];
    for (var f = 0; f < fincas.length; f++) {
        var devices = fincas[f].devices || [];
        for (var d = 0; d < devices.length; d++) {
            var dev = devices[d];
            if (dev.id === undefined || dev.id === null || !dev.name) { continue; }
            if (prefijo && ("" + dev.name).indexOf(prefijo) !== 0) { continue; }
            var tbName = "LIS-" + dev.name;
            if (vistos[tbName]) { continue; }
            vistos[tbName] = true;
            var meta = {};
            for (var k in metadata) { if (metadata.hasOwnProperty(k)) { meta[k] = metadata[k]; } }
            meta.tb_device = tbName;
            meta.az_id_descubierto = "" + dev.id;
            meta.az_finca = fincas[f].name || "";
            meta.az_alias = dev.alias || dev.name;
            salida.push({
                msg: { tb_device: tbName, az_id: dev.id, alias: dev.alias || dev.name },
                metadata: meta,
                msgType: "AGZOOM_DEVICE"
            });
        }
    }
}
if (!salida.length) {
    throw new Error("userdevices no devolvio dispositivos" + (prefijo ? " con prefijo " + prefijo : ""));
}
return salida;

